rs":{"text":"It"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ইট"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"/ɪt/"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"এটা / ইহা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"বস্তু, প্রাণী, আবহাওয়া"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"They"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"দেই"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"/ðeɪ/"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"তারা"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একাধিক ব্যক্তি বা বস্তু"}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"💡 মনে রাখার সহজ কৌশল He = ছেলে (He-এর \"H\" মনে করো Husband)। She = মেয়ে (She — \"শী\" শুনতে \"শ্রী\"-এর মতো, মেয়েলি)। It মানুষ নয় — চেয়ার, বই, কুকুর, বৃষ্টি সব \"It\"। কিন্তু বাচ্চা বা প্রিয় পোষা প্রাণীর ক্ষেত্রে he/she-ও বলা যায়। বাংলার \"তুই / তুমি / আপনি\" — তিনটারই ইংরেজি একটাই: You। ইংরেজিতে সম্মানের আলাদা শব্দ নেই, তাই এটা নিয়ে দুশ্চিন্তা করো না।"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৩ — am / is / are : কোনটা কখন?"}]},{"type":"paragraph","content":[{"type":"text","text":"এই তিনটি শব্দকে বলা হয় \"verb to be\"। এদের বাংলা অর্থ — হই, হও, হয়, আছি, আছ, আছে। কোন subject-এর সাথে কোনটা বসবে, সেটাই এখন শিখবো।"}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"৩.১ মূল নিয়ম (Golden Rule)"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Subject"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Verb"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উচ্চারণ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উদাহরণ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"I"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"am"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"অ্যাম /æm/"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"I am a student."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"He / She / It"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"is"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ইজ /ɪz/"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"He is a doctor."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একজন / একটি (singular noun)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"is"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ইজ /ɪz/"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"Rahim is my friend."}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"We / You / They"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"are"}}]}]},{"ty