  -- Lesson 2: This / That / These / Those  +  have / has

  values (v_part_1, 'This / That / These / Those  +  have / has', 'lesson-02', 'Lesson 2 from English Foundation.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"জিনিস দেখিয়ে বলা এবং \"আমার আছে\" বলা"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🎯 এই Lesson শেষে তুমি যা পারবে"}]},{"type":"paragraph","content":[{"type":"text","text":"১. যেকোনো জিনিস আঙুল দিয়ে দেখিয়ে ইংরেজিতে তার নাম বলতে পারবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"২. This / That / These / Those — চারটির পার্থক্য কোনো ভুল ছাড়াই বুঝবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"৩. একবচন থেকে বহুবচন (singular → plural) বানানোর ৬টি নিয়ম শিখবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"৪. have / has দিয়ে \"আমার আছে / তার আছে\" বলতে পারবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"৫. এদের negative ও question বানাতে পারবে (don''t have / Does he have?)।"}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🔄 শুরুর আগে — Lesson 1 ঝালাই করো (৫ সেকেন্ডে উত্তর দাও)"}]},{"type":"paragraph","content":[{"type":"text","text":"১. I ____ a student."}]},{"type":"paragraph","content":[{"type":"text","text":"২. He ____ busy."}]},{"type":"paragraph","content":[{"type":"text","text":"৩. They ____ farmers."}]},{"type":"paragraph","content":[{"type":"text","text":"৪. \"সে বাসায় নেই\" — ইংরেজি করো।"}]},{"type":"paragraph","content":[{"type":"text","text":"৫. \"তুমি কি ছাত্র?\" — ইংরেজি করো। উত্তর:"}]},{"type":"paragraph","content":[{"type":"text","text":"1. am"}]},{"type":"paragraph","content":[{"type":"text","text":"2. is"}]},{"type":"paragraph","content":[{"type":"text","text":"3. are"}]},{"type":"paragraph","content":[{"type":"text","text":"4. He is not at home. / He isn''t at home."}]},{"type":"paragraph","content":[{"type":"text","text":"5. Are you a student? তিনটার বেশি ভুল হলে Lesson 