":[{"type":"paragraph","content":[{"type":"text","text":"আমি চা পছন্দ করি।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সময়সূচি"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"The train leaves at 9 pm."}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ট্রেন রাত ৯টায় ছাড়ে।"}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"💡 চেনার সহজ উপায় বাংলা বাক্যের শেষে যদি থাকে — \"করি, করো, করে, খাই, যায়, পড়ে, থাকি\" — তাহলে সেটা Present Indefinite। যেমন: আমি ভাত খাই। সে স্কুলে যায়। তারা ক্রিকেট খেলে।"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ২ — মূল Structure"}]},{"type":"paragraph","content":[{"type":"text","text":"Subject  +  Verb (মূল রূপ)  +  Object"}]},{"type":"paragraph","content":[{"type":"text","text":"কিন্তু একটা নিয়ম আছে — Subject যদি He / She / It বা একজন কেউ হয়, তাহলে verb-এর শেষে s বা es বসবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"He / She / It  +  Verb + s / es"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Subject"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Verb-এর রূপ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উদাহরণ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"বাংলা"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"I / We / You / They"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"মূল রূপ (s নেই)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"They play cricket."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"তারা ক্রিকেট খেলে।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"He / She / It"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"verb + s / es"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"He plays cricket."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সে ক্রিকেট খেলে।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একজন (Rahim, my father)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"verb + s / es"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"Rahim plays cricket."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"রহিম ক্রিকেট খেলে।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"একাধিক (my brothers)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"মূল রূপ (s নেই)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"My brothers play cricket."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"আমার ভাইয়েরা ক্রিকেট খেলে।"}]}]}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🧠 উল্টো নিয়ম — এটাই সবচেয়ে বিভ্রান্তিকর বাংলায় \"রা\" থাকলে বহুবচন। ইংরেজিতে উল্টো — subject একবচন হলে verb-এ s বসে, বহুবচন হলে বসে না। He plays.  (একজন → s আছে)      They play.  (একাধিক → s নেই) মনে রাখো: \"s\" হয় subject-এ থাকবে, নাহয় verb-এ থাকবে — দুই জায়গায় একসাথে নয়।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"২.১ s / es বসানোর নিয়ম"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"নিয়ম"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কখন"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উদাহরণ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"+ s"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সাধারণ সব verb"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"play → plays,  read → reads,  work → works"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"+ es"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"শেষে s, sh, ch, x, o থাকলে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"wash → washes,  watch → watches,  go → goes,  fix → fixes"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"y → ies"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"y-এর আগে ব্যঞ্জনবর্ণ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"study → studies,  cry → cries,  carry → carries"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"y → ys"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"y-এর আগে স্বরবর্ণ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"play → plays,  say → says,  buy → buys"}]}]}]},{"type":"tableRow","content":[{"type