aph","content":[{"type":"pronounce","attrs":{"text":"They goes to market."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"They go to market."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"They বহুবচন → verb-এ s নেই।"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"I don''t never smoke."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"I never smoke."}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"never-এর সাথে আরেকটা \"না\" বসে না।"}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ৯ — আজকের হোমওয়ার্ক"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"✍️ ৩০ মিনিটের কাজ"}]},{"type":"paragraph","content":[{"type":"text","text":"১. এই Lesson-এর ১৫টি verb উচ্চারণ দেখে ৩ বার জোরে পড়ো।"}]},{"type":"paragraph","content":[{"type":"text","text":"২. প্রতিটি verb-এর He/She/It রূপ লেখো (go → goes, study → studies…)।"}]},{"type":"paragraph","content":[{"type":"text","text":"৩. তোমার সারাদিনের রুটিন নিয়ে ১০টি বাক্য লেখো।"}]},{"type":"paragraph","content":[{"type":"text","text":"৪. তোমার বাবা/মায়ের রুটিন নিয়ে ৫টি বাক্য লেখো — মনে রেখো, verb-এ s বসবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"৫. আয়নার সামনে ৫ বার বলো: \"What do you do? — I am a student. I study in class ____.\""}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"✅ তুমি বুঝবে কীভাবে যে Lesson 3 শেষ? যদি \"He\" দিয়ে যেকোনো বাক্য বানাতে গিয়ে verb-এ s বসাতে তোমার আর ভাবতে না হয় — অর্থাৎ \"He go\" মুখ দিয়ে বের হলেই কানে খট করে লাগে — তাহলে Lesson 3 তোমার হয়ে গেছে।"}]}]}]}'::jsonb, 'published', 'beginner', 53, now())
