  values (v_part_1, 'Past Tense — was / were + Past Indefinite', 'lesson-05', 'Lesson 5 from English Foundation.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"অতীতের কথা বলা"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🎯 এই Lesson শেষে তুমি যা পারবে"}]},{"type":"paragraph","content":[{"type":"text","text":"১. গতকাল / গত সপ্তাহে কী করেছিলে — সব ইংরেজিতে বলতে পারবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"২. was / were কখন বসে, নিখুঁতভাবে বুঝবে (am/is/are-এর অতীত রূপ)।"}]},{"type":"paragraph","content":[{"type":"text","text":"৩. verb-এর Past form (২য় রূপ) বানানোর নিয়ম ও ২৫টি Irregular Verb শিখবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"৪. -ed-এর তিন রকম উচ্চারণ শিখবে (/t/, /d/, /ɪd/) — এটা প্রায় কোনো বইয়ে থাকে না।"}]},{"type":"paragraph","content":[{"type":"text","text":"৫. Negative ও Question বানাতে পারবে: I didn''t go / Did you go?"}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🔄 শুরুর আগে — Lesson 4 ঝালাই করো"}]},{"type":"paragraph","content":[{"type":"text","text":"১. He ____ (write) a letter now."}]},{"type":"paragraph","content":[{"type":"text","text":"২. \"run\"-এর ing রূপ?"}]},{"type":"paragraph","content":[{"type":"text","text":"৩. না-বাচক করো: They are playing."}]},{"type":"paragraph","content":[{"type":"text","text":"৪. প্রশ্ন করো: She is cooking. উত্তর:"}]},{"type":"paragraph","content":[{"type":"text","text":"1. is writing"}]},{"type":"paragraph","content":[{"type":"text","text":"2. running"}]},{"type":"paragraph","content":[{"type":"text","text":"3. They aren''t playing."}]},{"type":"paragraph","content":[{"type":"text","text":"4. Is she cooking?"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ১ — was / were (am, is, are-এর অতীত রূপ)"}]},{"type":"paragraph","content":[{"type":"text","text":"Lesson 1-এ শিখেছিলে am / is / are। অতীতে সেগুলোই হয়ে যায় was / were। নিয়ম আগের মতোই সহজ।"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"বর্তমান"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"অতীত"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উচ্চারণ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Subject"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"am"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"was"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ওয়জ /wɒz/"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"I"}}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"is"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"was"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ওয়জ /wɒz/"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"He / She / It / একজন"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"are"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"were"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ওয়ার /wɜː(r)/"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"We / You / They / একাধিক"}]}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"I, He, 