text","text":"Subject  +  Verb-এর ২য় রূপ (Past form)  +  Object"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"💡 বড় সুখবর এখানে He/She/It-এর জন্য আলাদা কিছু নেই! সব subject-এর সাথে verb-এর একই রূপ বসে। I went.  He went.  They went.  — সবার জন্য একই। Present-এর মতো s/es-এর ঝামেলা নেই।"}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"২.১ Past form বানানোর নিয়ম (Regular Verb)"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"নিয়ম"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"কখন"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উদাহরণ"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"+ ed"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সাধারণ সব verb"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"play → played,  work → worked,  help → helped"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"+ d"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"শেষে e থাকলে"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"like → liked,  live → lived,  love → loved"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"y → ied"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"y-এর আগে ব্যঞ্জনবর্ণ"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"study → studied,  cry → cried,  carry → carried"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell