  -- Lesson 6: Future Tense — will / be going to

  values (v_part_1, 'Future Tense — will / be going to', 'lesson-06', 'Lesson 6 from English Foundation.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ভবিষ্যতের কথা বলা"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🎯 এই Lesson শেষে তুমি যা পারবে"}]},{"type":"paragraph","content":[{"type":"text","text":"১. কাল / আগামী সপ্তাহে কী করবে — সব ইংরেজিতে বলতে পারবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"২. will দিয়ে ভবিষ্যৎ বাক্য, না-বাচক (won''t) ও প্রশ্ন বানাতে পারবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"৩. \"be going to\" কখন ব্যবহার হয় এবং will-এর সাথে পার্থক্য বুঝবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"৪. প্রতিশ্রুতি, সিদ্ধান্ত ও পরিকল্পনা — তিনটার জন্য সঠিক গঠন বেছে নিতে পারবে।"}]},{"type":"paragraph","content":[{"type":"text","text":"৫. এই Lesson শেষে তোমার তিনটি মূল Tense-ই (Present, Past, Future) সম্পূর্ণ হবে।"}]}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"🔄 শুরুর আগে — Lesson 5 ঝালাই করো"}]},{"type":"paragraph","content":[{"type":"text","text":"১. I ____ (go) to Dhaka yesterday."}]},{"type":"paragraph","content":[{"type":"text","text":"২. \"buy\"-এর Past form?"}]},{"type":"paragraph","content":[{"type":"text","text":"৩. না-বাচক করো: He ate rice."}]},{"type":"paragraph","content":[{"type":"text","text":"৪. They ____ happy. (was/were) উত্তর:"}]},{"type":"paragraph","content":[{"type":"text","text":"1. went"}]},{"type":"paragraph","content":[{"type":"text","text":"2. bought"}]},{"type":"paragraph","content":[{"type":"text","text":"3. He didn''t eat rice."}]},{"type":"paragraph","content":[{"type":"text","text":"4. were"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"অংশ ১ — will দিয়ে ভবিষ্যৎ"}]},{"type":"paragraph","content":[{"type":"text","text":"ভবিষ্যতে কোনো কাজ হবে — এমন বোঝাতে। বাংলায় শেষে থাকে \"করব, যাবে, খাবে, পড়বে, থাকবে\"।"}]},{"type":"paragraph","content":[{"type":"text","text":"Subject  +  will  +  Verb (মূল রূপ)  +  Object"}]},{"type":"callout","attrs":{"variant":"note"},"content":[{"type":"paragraph","content":[{"type":"text","text":"💡 সবচেয়ে সহজ Tense — কারণ কিছুই বদলায় না সব subject-এর জন্য একই \"will\" বসে। He/She/It-এর জন্য আলাদা কিছু নেই, verb-এও কোনো পরিবর্তন নেই। I will go.  He will go.  They will go.  — সবার জন্য একই।"}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Word"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"উচ্চারণ"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"ব্যবহার"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"will"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"উইল /wɪl/"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"সব subject-এর সাথে (আধুনিক ইংরেজিতে এটাই স্বাভাবিক)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"shall"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"শ্যাল /ʃæl/"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"পুরোনো নিয়মে I / We-এর সাথে। এখন প্রস্তাব দিতে ব্যবহার হয় — Shall we go?"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"pronounce","attrs":{"text":"won''t"}}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"ওৌন্ট /wəʊnt/"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"will not-এর সংক্ষিপ্ত রূপ"}]}]}]},{"type":"tableRow